def _normalize_gender(gender):
    normalized = (gender or "male").strip().lower()
    if normalized not in ("male", "female"):
        raise ValueError(f'Unknown gender {gender!r}: expected "male" or "female".')
    return normalized


def get_gendered_notes(gender):
    """
    Return the (called, visited, support_session_contact_note) phrase banks
    matching `gender` ("male" or "female", case-insensitive; defaults to
    "male" when falsy for backward compatibility with inputs that don't
    specify a gender).
    """
    normalized = _normalize_gender(gender)
    return (
        GENDERED_CALLED[normalized],
        GENDERED_VISITED[normalized],
        GENDERED_SUPPORT_SESSION_CONTACT_NOTE[normalized],
    )
